pub fn compare_and_transition(
    &self,
    agent_id: &AgentId,
    expected_generation: u64,
    requested: AgentLifecycle,
) -> Result<AgentLifecycleState, FleetRegistryError> {
    let current = self.load_agent(agent_id)?.lifecycle;
    if current.generation != expected_generation {
        return Err(FleetRegistryError::StaleGeneration {
            agent_id: agent_id.clone(),
            expected: expected_generation,
            current: current.generation,
        });
    }
    let next = current.successor(requested)?;
    let layout = self.layout.agent(agent_id);
    match publish_lifecycle(layout.run_root(), &next)? {
        PublishOutcome::Published => Ok(next),
        PublishOutcome::AlreadyExists => {
            let actual = self.load_agent(agent_id)?.lifecycle.generation;
            Err(FleetRegistryError::StaleGeneration {
                agent_id: agent_id.clone(),
                expected: expected_generation,
                current: actual,
            })
        }
    }

/// Atomically publishes one intent after synchronizing its file. Unix fsyncs
/// the containing directory; Windows uses a same-directory write-through
/// replacement. An unresolved non-terminal intent cannot be overwritten.
pub fn write_intent(
    run_root: &Path,
    intent: &SignedSupervisorIntent,
) -> Result<(), SignedIntentError> {
    intent.validate()?;
    if let Some(existing) = read_intent(run_root)?
        && matches!(
            existing.status,
            SignedIntentStatus::Prepared
                | SignedIntentStatus::Queued
                | SignedIntentStatus::RecoveryRequired
        )
        && existing.grant_sha256 != intent.grant_sha256
    {
        return Err(SignedIntentError::Invalid(
            "another signed supervisor intent is unresolved".to_string(),
        ));
    }
    write_atomic_json(run_root, SIGNED_INTENT_FILE, intent)
}

/// Publishes an explicit operator recovery directive bound to one exact intent
/// digest. The directive never asserts successful completion; the only
/// repository-controlled recovery action is fail-closed abort.
pub fn write_recovery_directive(
    run_root: &Path,
    directive: &SignedIntentRecoveryDirective,
) -> Result<(), SignedIntentError> {
    directive.validate()?;
    write_atomic_json(run_root, SIGNED_INTENT_RECOVERY_FILE, directive)
}

fn write_atomic_json<T: Serialize>(
    run_root: &Path,
    file_name: &str,
    value: &T,
) -> Result<(), SignedIntentError> {
    std::fs::create_dir_all(run_root)?;
    let sequence = TEMP_SEQUENCE.fetch_add(1, Ordering::Relaxed);
    let nanos = SystemTime::now()
        .duration_since(SystemTime::UNIX_EPOCH)
        .map_err(|_| SignedIntentError::Invalid("system clock before epoch".to_string()))?
        .as_nanos();
    let temp = run_root.join(format!(".{file_name}.{nanos}.{sequence}.tmp"));
    let final_path = run_root.join(file_name);
    let bytes = serde_json::to_vec(value)?;
    let mut file = OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&temp)?;
    file.write_all(&bytes)?;
    file.sync_all()?;
    drop(file);
    publish::publish(&temp, &final_path)?;
    Ok(())
}

